function ringGauge(title,value,percent,caption,accent='cyan'){
 const pct=Math.max(0,Math.min(100,Number(percent)||0)),offset=339.292*(1-pct/100);
 return `<article class="telemetry-gauge ${accent}"><div class="gauge-head"><span>${title}</span><i class="live-pip"></i></div><div class="gauge-dial"><svg viewBox="0 0 132 132" role="img" aria-label="${title}: ${pct.toFixed(1)} percent"><circle class="gauge-track" cx="66" cy="66" r="54"/><circle class="gauge-value" cx="66" cy="66" r="54" stroke-dasharray="339.292" stroke-dashoffset="${offset.toFixed(2)}"/><circle class="gauge-inner" cx="66" cy="66" r="43"/></svg><div class="gauge-number"><b>${pct.toFixed(1)}<small>%</small></b><span>${caption}</span></div></div><p>${value}</p></article>`;
}
function liveTelemetry(){
 const s=state.strength,ready=s.ready,cap=ready?s.cap:160000n*10n**18n,supply=ready?s.supply:0n,staked=ready?s.staked:0n;
 const dexPol=ready&&s.dexPolReady?s.dexPol:0n;
 const issued=cap?Number(supply*10000n/cap)/100:0,stakedPct=supply?Number(staked*10000n/supply)/100:0,dexPolPct=cap?Number(dexPol*10000n/cap)/100:0;
 const fmtWell=n=>ready?`${fmt(n,18,2)} WELL7`:'Waiting for chain data';
 const polValue=ready?(s.dexPolReady?fmtWell(dexPol):'Pair not configured'):'Waiting for chain data';
 const maxN=Number(E.formatUnits(cap,18)),supplyN=Number(E.formatUnits(supply,18)),stakedN=Number(E.formatUnits(staked,18));
 const bar=(label,n,den,detail)=>`<div class="telemetry-row"><div><span>${label}</span><b>${detail}</b></div><div class="telemetry-track"><i style="--fill:${den?Math.max(0,Math.min(100,n/den*100)):0}%"></i></div></div>`;
 return `<section class="telemetry-panel"><header class="telemetry-heading"><div><div class="eyebrow">LIVE PROTOCOL TELEMETRY</div><h2>Deepwell, at chain level.</h2><p>Read directly from BNB Smart Chain Testnet. Token values stay in WELL7 units.</p></div><div class="telemetry-live"><i class="live-pip"></i><span>${ready?'LIVE SNAPSHOT':'CONNECTING'}</span><small>${ready?`BLOCK ${s.block.toLocaleString('en-GB')}`:'Waiting for RPC'}</small></div></header><div class="telemetry-grid"><div class="gauge-cluster">${ringGauge('SUPPLY MINTED',fmtWell(supply),issued,'of fixed cap','violet')}${ringGauge('WELL7 STAKED',fmtWell(staked),stakedPct,'of minted','cyan')}${ringGauge('DEX POL ALLOCATION',polValue,dexPolPct,'live pair reserve','mint')}</div><div class="supply-chart"><div class="chart-title"><div><span>SUPPLY &amp; STAKING</span><small>Live snapshot · WELL7</small></div><span class="chart-tag">ON-CHAIN</span></div><div class="chart-plot"><div class="chart-axis"><span>160k</span><span>120k</span><span>80k</span><span>40k</span><span>0</span></div><div class="chart-bars">${bar('Maximum supply',maxN,maxN,ready?fmtWell(cap):'160,000 WELL7')}${bar('Minted supply',supplyN,maxN,ready?fmtWell(supply):'—')}${bar('Currently staked',stakedN,maxN,ready?fmtWell(staked):'—')}${bar('DEX POL allocation',Number(E.formatUnits(dexPol,18)),maxN,polValue)}</div></div><div class="chart-legend"><i class="legend-cap"></i> FIXED CAP <i class="legend-minted"></i> MINTED <i class="legend-staked"></i> STAKED <i class="legend-pol"></i> DEX POL</div><p class="chart-footnote">DEX POL shows WELL7 currently held by the configured PancakeSwap V2 pair; its reserve can differ from the original allocation. No mock USD values.</p></div></div><footer class="telemetry-foot"><span><i class="live-pip"></i> Contract reads verified on chain</span><span>${farmList().length} pools <b>·</b> ${vaultList().length} stock vaults</span><a href="/strength/">Open protocol explorer ↗</a></footer></section>`;
}
